//! Decodes the checked-in envelope fixtures (testdata/ at the repo root,
//! regenerated by `cargo run --example gen_fixtures -p ferry-go`) and
//! asserts their shape. The Go runtime decodes the same two files in
//! runtime/fixture_test.go -- if the envelope's wire shape or version ever
//! drifts between the two languages, one side's decode breaks here instead
//! of silently misreading a byte stream at a bridge boundary.
//!
//! The fixtures are embedded with `include_bytes!` (resolved at host
//! compile time) rather than read at runtime: reading them from disk
//! inside the wasm32-wasip1 guest would need a WASI preopen reaching
//! outside this crate's directory, which is more machinery than a static
//! byte string needs.

use ferry_go::{Envelope, ErrorKind, WireError, ENVELOPE_VERSION};
use serde::Deserialize;

#[derive(Deserialize)]
struct FixtureOut {
    message: String,
}

static OK_FIXTURE: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../testdata/envelope_ok.msgpack"
));
static ERR_FIXTURE: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../testdata/envelope_err.msgpack"
));

#[test]
fn ok_fixture_decodes() {
    let envelope: Envelope = rmp_serde::from_slice(OK_FIXTURE).expect("decode envelope");
    assert_eq!(envelope.version, ENVELOPE_VERSION);
    assert!(envelope.ok);
    let out: FixtureOut = rmp_serde::from_slice(&envelope.payload).expect("decode payload");
    assert_eq!(out.message, "fixture");
}

#[test]
fn err_fixture_decodes() {
    let envelope: Envelope = rmp_serde::from_slice(ERR_FIXTURE).expect("decode envelope");
    assert_eq!(envelope.version, ENVELOPE_VERSION);
    assert!(!envelope.ok);
    let err: WireError = rmp_serde::from_slice(&envelope.payload).expect("decode error payload");
    assert_eq!(err.kind, ErrorKind::Guest);
    assert_eq!(err.message, "fixture error");
}
